        Number(inputs.d5) || 0,
        Number(inputs.d6) || 0,
      ].sort((a, b) => a - b);
      const n = arr.length;
      // Linear interpolation method for percentile
      const index = (p / 100) * (n - 1);
      const lowerIndex = Math.floor(index);
      const fraction = index - lowerIndex;
      let val = arr[lowerIndex];
      if (fraction > 0 && lowerIndex + 1 < n) {
        val = arr[lowerIndex] + fraction * (arr[lowerIndex + 1] - arr[lowerIndex]);
      }
      return {
        primary: { label: p + '. Perzentil (P' + p + ')', value: val.toFixed(2), unit: '' },
        details: [
          { label: 'Sortierte Reihe', value: arr.join(' ; ') },
          { label: 'Bedeutung', value: p + ' % aller Messwerte sind kleiner oder gleich ' + val.toFixed(2) },
          { label: 'Perzentil-Rang Index', value: (index + 1).toFixed(2) + ' von ' + n },
